from sqlalchemy import Column, Integer, String, DateTime, ForeignKey, Enum, Text, Index
from sqlalchemy.dialects import mysql
from sqlalchemy.orm import declarative_base
from sqlalchemy.sql import func
from .users import Base
class PropertyVisit(Base): __tablename__ = "property_visits"; id = Column(mysql.BIGINT(unsigned=True), primary_key=True, autoincrement=True); property_listing_id = Column(mysql.BIGINT(unsigned=True), ForeignKey("property_listings.id", ondelete="CASCADE", onupdate="CASCADE"), nullable=False); buyer_user_id = Column(mysql.BIGINT(unsigned=True), ForeignKey("users.id", ondelete="CASCADE", onupdate="CASCADE"), nullable=False); owner_user_id = Column(mysql.BIGINT(unsigned=True), ForeignKey("users.id", ondelete="CASCADE", onupdate="CASCADE"), nullable=False); scheduled_at = Column(DateTime, nullable=False); status = Column(Enum("REQUESTED","PROPOSED","CONFIRMED","DECLINED","CANCELLED","COMPLETED"), nullable=False, server_default="REQUESTED"); initiator = Column(Enum("BUYER","OWNER"), nullable=False); note = Column(Text, nullable=True); created_at = Column(DateTime, server_default=func.current_timestamp(), nullable=False); updated_at = Column(DateTime, server_default=func.current_timestamp(), nullable=False); __table_args__ = (Index("idx_visits_buyer", "buyer_user_id"), Index("idx_visits_owner", "owner_user_id"), Index("idx_visits_listing", "property_listing_id"),)
